from lib import *
S = SS('w105')
steps = [
    step("两个容器 ta、tb 放在 Docker 的 Linux 虚拟机里(内核 7.0.14-linuxkit,桥的 MTU 1500),中间真的建了 GRE、VXLAN、WireGuard 和 IPsec ESP(隧道模式,AES-GCM-128)四种隧道。每条隧道里 ping 一个固定大小的内层 IP 包,在 ta 的 eth0 上抓外层 IP 包,看每个包多出多少字节。内层 84、85、100、528、1028、1229 字节时:GRE 恒定 +24(外层 IP 20 + GRE 头 4);VXLAN 恒定 +50(外层 IP 20 + UDP 8 + VXLAN 8 + 内层以太网头 14);WireGuard 在 +60 到 +72 之间变化(内层 528 字节时刚好 +60,84 字节 +72,85 字节 +71——内层包会先补零到 16 的倍数,再加外层 IP 20、UDP 8、头 16、认证标签 16);IPsec ESP 在 +55 到 +56 之间(84 字节 +56,85 字节 +55,按 4 字节边界填充)。外层是 IPv6 时每个包再多 20 字节——这一点没有测,是计算。", t=tl(S(1)), mark=lidx(S(1), 'GRE      ', 'VXLAN   ', 'WireGuard   '), done=lidx(S(1), 'IPsec ESP(隧道模式', 'GRE 每个包恒定'), b=bars([['GRE', 24, '+24'], ['IPsec ESP', 56, '+55~56'], ['VXLAN', 50, '+50'], ['WireGuard', 72, '+60~72']], 72, mark=[3], done=[0, 1, 2]), kv=KV([['GRE', '恒定 +24'], ['VXLAN', '恒定 +50(含内层以太网头)'], ['WireGuard', '+60~+72,内层补到 16 的倍数'], ['IPsec ESP', '+55~+56,填充到 4 字节']], ['WireGuard'])),
    step("内核给每种隧道接口自动设的 MTU:GRE 的 g0 是 1476(1500 − 24),WireGuard 的 w0 是 1420(不是 1440,给外层是 IPv6 的情况留余地),VXLAN 的 v0 是 1500。VXLAN 这个 1500 是个坑:建它时我没有指定底层网卡,内核不知道外层走哪块网卡,就没有减去那 50 字节;同样的 VXLAN 加上 dev eth0 参数后(v1)MTU 自动成了 1450。IPsec ESP 在 Linux 里不是一个网络接口,没有接口 MTU,路径 MTU 靠路由和 xfrm 状态推算。", t=tl(S(2)), mark=lidx(S(2), 'g0  默认', 'w0  默认'), done=lidx(S(2), 'v0  默认', 'v1(VXLAN', 'IPsec ESP 在 Linux'), kv=KV([['GRE', '1476'], ['WireGuard', '1420'], ['VXLAN(没指定 dev)', '1500,要自己调'], ['VXLAN(dev eth0)', '1450']], ['VXLAN(没指定 dev)'])),
    step("内层包比隧道 MTU 大 1 字节时分别怎样(ping -M do 带 DF,-M dont 不带)。带 DF:GRE 1477、WireGuard 1421、VXLAN(MTU 1450)1451 都是本地直接报 message too long,一个外层包都没发出去。不带 DF:内核先把内层包分片再各自封装——GRE 1477 字节发出 [1500, 45] 两个外层包(各自都带 DF),VXLAN 1451 字节发出 [1494, 77] 两个。把 VXLAN 的 MTU 留在 1500:第一个内层 1500 字节的包通过了,外层是分片的 [1500(第一片), 70(偏移 1480)];紧接着第二个 ping 就被本地拒绝(message too long, mtu=1450),查路由发现内核给这个目的地记下了 “mtu 1450” 的路径 MTU 例外(约 10 分钟有效)。GRE 把 MTU 强改成 1500:带 DF 的 1500 字节包得到 Frag needed and DF set (mtu = 1476),0/2;不带 DF 的两个里只收到 1 个,且只看到 [1500, 68] 一对外层包,另一个没有发出外层包就没了(原因我没有进一步查,看起来是内核先丢掉第一个包、学到路径 MTU 1476 之后才开始分片)。", t=tl(S(3)), mark=lidx(S(3), '内层 1477 字节 DF=是', '内层 1421 字节 DF=是', '内层 1451 字节 DF=是'), done=lidx(S(3), '内层 1477 字节 DF=否', '内层 1451 字节 DF=否', "(1500, 0, '+')", '← 发过一个超大包后', '接口 MTU 1500,内层 1500 字节 DF=是', '接口 MTU 1500,内层 1500 字节 DF=否'), kv=KV([['DF=是,超 MTU', '本地 message too long'], ['DF=否,超 MTU', '先在内层分片,各自封装'], ['MTU 配大了的 VXLAN', '外层分片 + 内核学到 PMTU'], ['GRE 强改 1500', 'Frag needed (mtu 1476)']], ['MTU 配大了的 VXLAN'])),
    step("回到这台 Mac 本机的网卡 en0 上,用自己写的最小 IP-in-UDP 封装(内层 IP 包加 32 字节隧道头,装进一个 UDP 数据报,发到文档专用地址 198.51.100.1:51820,不会到达真实主机)抓包。内层 1280 字节:外层 IP 包 1340 字节,一个包;1400 → 1460;1420 → 1480;1440 → 1500,刚好一个包(满 MTU);内层 1441 → 外层 1501,en0 上发出 [1500, 21] 两个包,偏移 0 和 1480;1480 → [1500, 60];1500 → [1500, 80]。内层 ≤ 1500 − 20 − 8 − 32 = 1440 字节时刚好一个包,再大一个字节外层就被分成两片。", t=tl(S(4)), mark=lidx(S(4), '      1440  ', '      1441  '), done=lidx(S(4), '      1280  ', '      1480  ', '      1500  ', '外层 IP 包不能超过'), b=bars([['内层 1440', 1500, '1500 字节,1 个包'], ['内层 1441', 1501, '1501 字节 → [1500, 21]'], ['内层 1500', 1560, '1560 字节 → [1500, 80]']], 1560, mark=[1], done=[0, 2]), kv=KV([['≤ 1440', '外层不超过 1500,一个包'], ['1441', '外层 1501,分成 [1500, 21]'], ['IP 分片', '偏移 0 和 1480']], ['1441'])),
    step("分片放大丢包,这次是真的测:在 ta 的 eth0 上用 tc netem 给出站包加 1% 的随机丢包,在 VXLAN 隧道里连续 ping 5000 次、重复 3 轮,共 15000 个请求。内层 84 字节(1 个外层包):丢 149 个 = 0.99%;内层 1450 字节(接口 MTU 1450,外层 1500 字节,仍是 1 个外层包):丢 144 个 = 0.96%;内层 1500 字节(接口 MTU 1500,一个请求变成 2 个外层包):丢 260 个 = 1.73%。按公式 1 − 0.99² = 1.99%,这一轮偏低一点(三轮每轮 5000 个的标准误差约 0.11 个百分点);我这个脚本前面几次完整跑出来的同一项分别是 1.91%、1.94%、1.87%、2.24%,所以大致就是翻倍,不是精确的 1.99%。", t=tl(S(5)), mark=lidx(S(5), '内层 1500 字节(一个请求'), done=lidx(S(5), '基线:内层 84', '内层 1450 字节(1 个外层包)'), b=bars([['内层 84 字节', 0.99, '0.99%'], ['内层 1450 字节', 0.96, '0.96%'], ['内层 1500 字节', 1.73, '1.73%']], 1.99, mark=[2], done=[0, 1]), kv=KV([['1 个外层包', '丢包率约 1%'], ['2 个外层包', '约 1.7%~2.2%(几轮不同)'], ['公式', '1 − 0.99² = 1.99%']], ['2 个外层包'])),
    step("隧道对 TCP 效率的影响(实测):tb 上起一个 TCP 服务,ta 向它发 10,000,000 字节,在 eth0 上抓出站的所有帧并把以太网帧长度加起来(先关掉 tso / gso / gro,免得网卡把帧合并)。不用隧道:MSS 1448,6916 个帧,共 10,456,464 字节,多 4.6%;GRE(MTU 1476):MSS 1424,7039 个帧,多 6.3%;WireGuard(MTU 1420):MSS 1368,7315 个帧,多 9.2%;VXLAN(MTU 1450):MSS 1398,7158 个帧,多 8.3%。MTU 错配(VXLAN 接口 MTU 仍是 1500)那一行:连接建立时 MSS 是 1448,传的过程中降到 1398(内核学到了路径 MTU),抓到 10 个 IP 分片,总量 10,832,014 字节,也多 8.3%——TCP 带着 DF,所以错配只在开头那几个包上付出了代价,没有一直分片。", t=tl(S(6)), mark=lidx(S(6), 'WireGuard(接口 MTU 1420)', 'VXLAN(MTU 错配'), done=lidx(S(6), '不用隧道,直连', 'GRE(接口 MTU 1476)', 'VXLAN(接口 MTU 1450)', 'MSS 栏是'), b=bars([['不用隧道', 4.6, '+4.6%'], ['GRE', 6.3, '+6.3%'], ['VXLAN', 8.3, '+8.3%'], ['WireGuard', 9.2, '+9.2%']], 9.2, mark=[3], done=[0, 1, 2]), kv=KV([['不用隧道', 'MSS 1448,多 4.6%'], ['WireGuard', 'MSS 1368,多 9.2%'], ['错配的 VXLAN', 'MSS 1448 → 1398,10 个分片']], ['错配的 VXLAN'])),
    step("这台 Mac 本机有哪些隧道类接口?读 ifconfig 的接口名与 MTU(不看任何地址):gif0 MTU 1280、stf0 MTU 1280、utun0 MTU 1500、utun1 MTU 1380、utun2 MTU 2000、utun3 MTU 1000,共 6 个,MTU 各不相同。utun 就是 macOS 上 VPN 软件创建的虚拟网卡。数据最终走哪个接口,取决于路由表(w11);路径 MTU 也就取决于那个接口的 MTU(例如走 MTU 1380 的接口时,TCP 的 MSS 应该是 1340)。", t=tl(S(7)), mark=lidx(S(7), 'utun1', 'utun3'), done=lidx(S(7), 'gif0', 'stf0', 'utun0', 'utun2', '共 6 个'), kv=KV([['gif0 / stf0', 'MTU 1280'], ['utun0~3', '1500 / 1380 / 2000 / 1000'], ['路径 MTU', '由路由选中的接口决定']], ['路径 MTU'])),
]
A = mkartw('w105', 105, '网络协议,VPN,隧道,封装,MTU,分片,WireGuard,GRE,VXLAN,IPsec,真实验证,动画演示',
    '在 Docker 的 Linux 里搭真的 GRE、VXLAN、WireGuard、IPsec ESP 隧道:每个包额外 +24 / +50 / +60~72 / +55~56 字节;VXLAN 不指定 dev 时 MTU 是 1500 不是 1450;超过隧道 MTU 时带 DF 本地报错、不带 DF 先在内层分片;1% 丢包下分成两个外层包的内层包丢失率 0.99% → 1.73%;TCP 开销 4.6% → 6.3% / 8.3% / 9.2%。',
    'VPN 隧道把你的包装进另一个包里。多出来的那几十个字节,会把 MTU、分片、丢包率和 TCP 的 MSS 一连串地牵动。这一篇在 Docker 的 Linux 虚拟机里搭了真的 GRE、VXLAN、WireGuard 和 IPsec ESP 隧道,在外层网卡上抓包,把每个包多多少字节、MTU 配错会怎样、丢包怎么被放大、TCP 效率差多少,逐项量出来。',
    [('+24 / +50 / +60~72', 'GRE / VXLAN / WireGuard 每个包额外的字节(实测;ESP 是 +55~56)'), ('1450 vs 1500', 'VXLAN 指定底层网卡 dev 时接口 MTU 自动是 1450;不指定则是 1500,要自己调'), ('4.6% → 9.2%', '10 MB TCP 传输的线上额外开销:不用隧道 4.6%,GRE 6.3%,VXLAN 8.3%,WireGuard 9.2%')],
    [('封装开销', '<p>GRE 恒定 +24,VXLAN 恒定 +50(含内层以太网头),WireGuard +60~+72、IPsec ESP +55~+56——后两者要把内层包补齐到 16 或 4 字节的倍数,所以随内层大小变化。内层 MTU = 链路 MTU − 额外字节。</p>'),
     ('接口 MTU', '<p>内核给 GRE 自动设 1476、WireGuard 1420;VXLAN 只有指定了底层网卡才会自动减 50 字节。隧道接口的 MTU 要和外层链路配套,否则大包会被分片或被丢。</p>'),
     ('超过 MTU 之后', '<p>内层包带 DF 就在本地被拒绝(message too long);不带 DF 就先在内层分片、各片再封装。外层分片只在隧道接口 MTU 配得比链路允许的大时出现,而内核会在发出第一个超大包后学到更小的路径 MTU。</p>'),
     ('en0 上的分片', '<p>自己写的 IP-in-UDP 封装:内层 ≤ 1440 字节时外层刚好 1500 字节一个包,1441 字节起外层被分成两片。</p>'),
     ('丢包放大', '<p>一个内层包变成两个外层包,任何一个丢了都算丢。1% 丢包下实测丢失率约翻倍(0.99% → 1.73%,几轮在 1.7%~2.2% 之间)。</p>'),
     ('TCP 效率', '<p>隧道让 MSS 变小、每段多出头部:10 MB 传输的额外开销从 4.6%(不用隧道)升到 GRE 6.3%、VXLAN 8.3%、WireGuard 9.2%。MTU 错配时 TCP 带着 DF,开头几个包付代价后 MSS 降下来,不会一直分片。</p>'),
     ('本机的隧道接口', '<p>6 个隧道类接口 MTU 各不相同,路径 MTU 取决于路由选中的接口。</p>')],
    steps,
    [ENV_W + '。一到三、五、六节在 Docker Desktop 的 Linux 虚拟机(内核 7.0.14-linuxkit)里的两个容器 ta、tb 之间做,容器放在一个 MTU 1500 的 Docker 桥上,各自 NET_ADMIN 权限,用 iproute2 / wireguard-tools 建隧道,tcpdump 在 ta 的 eth0 上抓 ta→tb 方向的外层包;WireGuard 密钥、ESP 密钥都是实验用的一次性值;关掉了容器里的 IPv6 以减少背景包;ESP 隧道的状态和策略用 ip xfrm 手工建立;第五节用 tc netem 给 ta 的 eth0 出站加 1% 随机丢包(只影响请求方向),每轮 5000 个、共 3 轮;第六节用 Python 套接字单连接发 10,000,000 字节,先用 ethtool 关掉 tso / gso / gro,统计的是 ta→tb 方向的以太网帧长度;第四节是这台 Mac 的 en0 上自己写的 IP-in-UDP,目的地址是文档专用的 198.51.100.1,不会到达真实主机;第七节只读接口名与 MTU',
     '没有验证:IPIP 隧道——在这个 Docker 虚拟机里创建 ipip 接口会让 Docker 后端崩溃,所以没有测;GRE 之外的 IPv6 外层(外层 IPv6 的额外字节是计算值);真实网络里 PMTUD 依赖的 ICMP 3/4 报文被中间设备丢弃的情况(见 w16);NAT 穿越下 UDP 隧道的保活;真实广域网上 WireGuard 的握手与吞吐;MSS 钳制设备的真实效果(见 w65);隧道内再套隧道的叠加开销;分片放大丢包的数字每轮不同(几次完整运行在 1.7%~2.2% 之间),不是精确的 1.99%'],
    '隧道封装与 MTU')
